<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf6f1;--card:#fff;--accent:#7a4b33;--accent-2:#b07a57;--muted:#5f4a43;--shadow:0 12px 30px rgba(120,80,60,.08);font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto}
    body{margin:0;background:var(--bg);color:var(--muted)}
    .wrap{max-width:920px;margin:0 auto;padding:28px}
    header{border-bottom:1px solid rgba(122,75,51,.06);padding-bottom:12px}
    nav{display:flex;gap:16px;align-items:center}
    nav a{color:var(--accent);text-decoration:none;font-weight:600}
    .hero{display:grid;grid-template-columns:1fr;gap:16px;padding:28px 0}
    .badge{display:inline-block;padding:6px 10px;background:linear-gradient(90deg,rgba(176,122,87,.08),rgba(122,75,51,.04));border-radius:8px;color:var(--accent-2);font-weight:700}
    .profile{display:flex;gap:18px;align-items:center}
    .portrait{width:110px;height:110px;border-radius:12px;background:linear-gradient(180deg,#f3e9e2,#fff);display:flex;align-items:center;justify-content:center;color:var(--accent);font-weight:700;box-shadow:var(--shadow);border:1px solid rgba(122,75,51,.04)}
    .meta p{margin:0;color:var(--muted)}

    .grid{display:grid;grid-template-columns:1fr;gap:18px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:10px;border:1px solid rgba(122,75,51,.04);box-shadow:var(--shadow)}

