  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="logo" style="font-weight:800;color:var(--accent)">{{BUSINESS_NAME}}</div>
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="approach.html">Discover</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html" aria-current="page">About</a>
        <a href="book.html">Book</a>
      </nav>
    </div>
  </header>

  <main class="wrap" role="main">
    <section class="hero" data-reveal>
      <div>
        <span class="badge">Integrative · Practical</span>
        <h1 style="margin-top:12px;color:var(--accent)">A pragmatic, whole-life approach</h1>
        <p class="small">We blend conventional insight with lifestyle strategies so you can make steady progress without chaos. Our work is collaborative, evidence-aware, and designed to fit the rhythms of your life.</p>
      </div>
      <aside>
        <div class="card" style="text-align:left">
          <div class="profile">
            <div class="portrait">PR</div>
            <div class="meta">
              <p style="font-weight:700;color:var(--accent-2)">Practitioner: Practical Roots</p>
              <p class="small">Clinical background in integrative medicine and behavioral coaching. Focus on usable plans not inflated promises.</p>
            </div>
          </div>
          <div style="margin-top:12px"><a class="cta" href="{{PRIMARY_CTA_URL}}" style="display:inline-block;padding:8px 12px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none;font-weight:700">{{PRIMARY_CTA_LABEL}}</a></div>
        </div>
      </aside>
    </section>

    <section class="grid" style="margin-top:18px">
      <div class="card" data-reveal>
        <h2 style="color:var(--accent)">Approach</h2>
        <p class="small">We map the whole picture—sleep, digestion, stress load, movement, medication context—and co-create lower-friction changes. Each plan has clear, measurable actions tailored to your schedule.</p>
        <ul class="small">
          <li>Clarity first: we identify 1–3 high-leverage priorities</li>
          <li>Small experiments: short, trackable adjustments to try for 2–4 weeks</li>
          <li>Optimize: iterate based on results and lived experience</li>
        </ul>
      </div>

      <div class="card" data-reveal>
        <h2 style="color:var(--accent)">Training & credentials</h2>
        <p class="small">Clinician training in integrative approaches, ongoing education in sleep and behavioral medicine, and years of coaching experience with adults navigating complex schedules.</p>
        <p class="small" style="margin-top:6px">We prioritize safety and coordinate with your medical providers when needed.</p>
      </div>
    </section>

    <section style="margin-top:20px" data-reveal>
      <div class="card">
        <h2 style="color:var(--accent)">Philosophy</h2>
        <p class="small">Change happens best when it fits the life you already have. We aim to minimize disruption while improving signal—small consistent shifts, not dramatic upheaval.</p>
      </div>
    </section>

    <section style="margin-top:20px" data-reveal>
      <h2 style="color:var(--accent)">Stories from people who've worked with us</h2>
      <div class="grid" style="margin-top:12px">
        <blockquote class="card small" data-reveal>“Clear plans that actually fit my workweek. I could see progress in the first two weeks.” — A.</blockquote>
        <blockquote class="card small" data-reveal>“The VIP day helped me walk away with a plan I could follow immediately—no fluff.” — T.</blockquote>
      </div>
    </section>

    <section style="margin-top:20px" data-reveal>
      <div class="card">
        <h3 style="color:var(--accent)">Work with us</h3>
        <p class="small">If you're ready to map priorities and start a realistic plan, book a conversation. We will talk through which offering best matches your needs and timeline.</p>
        <p class="small" style="margin-top:8px">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p style="margin-top:10px"><a href="{{PRIMARY_CTA_URL}}" style="background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none;font-weight:700">Schedule a conversation</a></p>
      </div>
    </section>

  </main>

  <script>
    // Scroll reveal with prefers-reduced-motion support (duplicate-friendly safe-init)
    (function(){
      if(window.__reveal_initialized) return; window.__reveal_initialized = true;
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var list = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ list.forEach(function(el){el.classList.add('is-visible');}); return; }
      if('IntersectionObserver' in window){
        var observer = new IntersectionObserver(function(entries){
          entries.forEach(function(entry){ if(entry.isIntersecting){ entry.target.classList.add('is-visible'); observer.unobserve(entry.target);} });
        },{threshold:0.12});
        list.forEach(function(el){observer.observe(el);});
      } else { list.forEach(function(el){el.classList.add('is-visible');}); }
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff8f3;--accent:#8a5339;--muted:#5f4b43;--card:#fff;--accent-2:#c28f6a;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto}
    body{margin:0;background:var(--bg);color:var(--muted)}
    .wrap{max-width:920px;margin:0 auto;padding:28px}
    nav{display:flex;gap:14px;align-items:center}
    nav a{color:var(--accent);text-decoration:none;font-weight:600}
    header{border-bottom:1px solid rgba(138,83,57,.06);padding-bottom:12px}
    .grid{display:grid;grid-template-columns:1fr;gap:18px}
    .card{background:var(--card);padding:18px;border-radius:10px;border:1px solid rgba(138,83,57,.04)}
    label{display:block;font-size:14px;margin-bottom:6px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(90,70,60,.08);box-sizing:border-box}
    button{background:var(--accent);color:#fff;padding:10px 14px;border:0;border-radius:8px;font-weight:700}
    .try{background:transparent;border:2px solid var(--accent);color:var(--accent);padding:8px 12px;border-radius:8px;font-weight:700}

    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(15,10,8,.32);display:flex;align-items:center;justify-content:center;z-index:60}
    .modal{background:#fff;padding:20px;border-radius:12px;max-width:560px;width:94%;box-shadow:0 18px 50px rgba(0,0,0,.22)}
    .hidden{display:none}

    /* breathing circle */
    .breath-wrap{display:flex;flex-direction:column;align-items:center;gap:12px}
    .circle{width:140px;height:140px;border-radius:50%;background:radial-gradient(circle at 30% 30%, rgba(194,143,106,.14), rgba(138,83,57,.06));display:flex;align-items:center;justify-content:center;color:var(--accent);font-weight:700}

    [data-reveal]{opacity:0;transform:translateY(14px);transition:opacity .6s ease, transform .6s ease}
    [data-reveal].is-visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){[data-reveal]{opacity:1;transform:none;transition:none}}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div style="font-weight:800;color:var(--accent)">{{BUSINESS_NAME}}</div>
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="approach.html">Discover</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">About</a>
        <a href="book.html" aria-current="page">Book</a>
      </nav>
    </div>
  </header>

  <main class="wrap" role="main">
    <section class="grid" data-reveal>
      <div class="card">
        <h1 style="margin-top:0;color:var(--accent)">Book a session</h1>
        <p class="small">Select a date and share a few details so we can prepare. If you prefer, call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
        <form id="bookingForm" style="margin-top:12px">
          <label for="name">Full name</label>
          <input id="name" name="name" required />
          <label for="email" style="margin-top:8px">Email</label>
          <input id="email" name="email" type="email" required />
          <label for="service" style="margin-top:8px">Service</label>
          <select id="service" name="service">
            <option>Orientation Visit (60 min)</option>
            <option>Renewal Series (6-week)</option>
            <option>VIP Integration Day</option>
          </select>
          <label for="notes" style="margin-top:8px">A brief note (goals or concerns)</label>
          <textarea id="notes" name="notes" rows="4"></textarea>
          <div style="display:flex;gap:10px;margin-top:12px;align-items:center">
            <button type="submit">Request booking</button>
            <button type="button" class="try" id="tryNowBtn">Try it now</button>
          </div>
        </form>
      </div>

      <aside class="card" data-reveal>
        <h3 style="color:var(--accent)">Need help choosing?</h3>
        <p class="small">If you're unsure which path fits, request a short consult or use the phone number. We help you choose the pathway that matches your objectives and lifestyle.</p>
        <p class="small" style="margin-top:8px">We also offer a guided micro-exercise you can try now to help orient your priorities—no booking required.</p>
        <div style="margin-top:10px"><a href="#" id="tryNowLink" class="try">Open guided exercise</a></div>
      </aside>
    </section>
  </main>

  <!-- Modal: Guided exercise (breathing, journaling, intention) -->
  <div id="modal" class="modal-backdrop hidden" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
    <div class="modal" role="document">
      <h2 id="modalTitle" style="margin-top:0;color:var(--accent)">Guided: Pause and orient</h2>
      <div id="modalContent">
        <div class="breath-wrap" id="stepArea">
          <div class="circle" id="breathCircle">Breathe</div>
          <p id="stepText" class="small">A short guided exercise to slow your body and notice what's most important right now.</p>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button id="nextBtn">Start</button>
            <button id="closeBtn" class="try">Close</button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // booking form simple handler
    (function(){
      var form = document.getElementById('bookingForm');
      form.addEventListener('submit', function(e){
        e.preventDefault();
        var name = form.name.value || 'Guest';
        alert('Thanks, ' + name + '. We received your request and will follow up to confirm.');
        form.reset();
      });
    })();

    // Modal and guided exercise logic
    (function(){
      var modal = document.getElementById('modal');
      var tryBtn = document.getElementById('tryNowBtn');
      var tryLink = document.getElementById('tryNowLink');
      var closeBtn = document.getElementById('closeBtn');
      var nextBtn = document.getElementById('nextBtn');
      var stepText = document.getElementById('stepText');
      var breathCircle = document.getElementById('breathCircle');
      var step = 0; var timer = null; var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      function openModal(){ modal.classList.remove('hidden'); document.body.style.overflow='hidden'; nextBtn.focus(); step=0; stepText.textContent='A short guided exercise to slow your body and notice priorities.'; breathCircle.textContent='Breathe'; breathCircle.style.transform='scale(1)'; }
      function closeModal(){ modal.classList.add('hidden'); document.body.style.overflow=''; clearInterval(timer); }

      tryBtn.addEventListener('click', openModal);
      tryLink.addEventListener('click', function(e){ e.preventDefault(); openModal(); });
      closeBtn.addEventListener('click', closeModal);

      // Simple sequence: 1) breathing (3 cycles), 2) journaling prompt (60s), 3) intention setting
      nextBtn.addEventListener('click', function(){
        if(step===0){ startBreathing(); nextBtn.textContent='Next'; step=1; }
        else if(step===1){ startJournaling(); nextBtn.textContent='Next'; step=2; }
        else if(step===2){ startIntention(); nextBtn.textContent='Done'; step=3; }
        else { closeModal(); }
      });

      function animatePulse(durationMs, cycles){
        if(prefersReduced){ breathCircle.style.transform='none'; return Promise.resolve(); }
        return new Promise(function(resolve){
          var cycle=0; breathCircle.style.transition='transform 1200ms ease-in-out';
          function run(){
            breathCircle.style.transform='scale(1.18)';
            setTimeout(function(){ breathCircle.style.transform='scale(1)'; cycle++; if(cycle<cycles){ setTimeout(run, 300); } else { resolve(); } }, 1200);
          }
          run();
        });
      }

      function startBreathing(){
        stepText.textContent='Three slow breaths: inhale for 4, hold 2, exhale 6. Follow the circle.';
        // animate pulse 3 cycles
        animatePulse(0,3).then(function(){ stepText.textContent='Nice. When ready, go to the next step.'; });
      }

      function startJournaling(){
        stepText.textContent='Take 60 seconds to jot down: What matters most for your energy and time this week?';
        var start = Date.now();
        var duration = 60 * 1000; // 60s
        // countdown in circle
        var interval = setInterval(function(){
          var remaining = Math.max(0, duration - (Date.now() - start));
          var sec = Math.ceil(remaining/1000);
          breathCircle.textContent = sec + 's';
